package io.quarkusio;

import io.quarkiverse.roq.testing.RoqAndRoll;
import io.quarkus.test.junit.QuarkusTest;
import io.restassured.RestAssured;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.condition.DisabledIfSystemProperty;

/**
 * Crawls the site generated by {@code @RoqAndRoll}. Skipped when {@code test.url} points
 * at an already served site, which {@link RemoteLinkCrawlerTest} crawls instead.
 */
@QuarkusTest
@RoqAndRoll
@DisabledIfSystemProperty(named = "test.url", matches = ".+")
@Tag("slow")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
public class LocalLinkCrawlerTest {

    private LinkCrawler crawler;

    // RestAssured only points at the Roq server once a test is running, so the crawler
    // cannot be created in a @BeforeAll.
    private synchronized LinkCrawler crawler() {
        if (crawler == null) {
            crawler = new LinkCrawler(RestAssured.baseURI + ":" + RestAssured.port);
        }
        return crawler;
    }

    @AfterAll
    void stopCrawler() {
        if (crawler != null) {
            crawler.close();
        }
    }

    @Test
    void crawlAndCheckLinks() throws InterruptedException {
        crawler().crawlAndCheckLinks();
    }

    @Test
    void crawlAndCheckImages() throws InterruptedException {
        crawler().crawlAndCheckImages();
    }

    @Test
    void crawlAndCheckFragmentAnchors() throws InterruptedException {
        crawler().crawlAndCheckFragmentAnchors();
    }
}
